import fs from 'node:fs';
import path from 'node:path';
// Counts PLANT in each file it is given, and reports one site outside the family's scope.
export function collect({ root, paths }) {
  const sites = paths.flatMap((p) => (fs.readFileSync(path.join(root, p), 'utf8').match(/PLANT/g) ?? []).map(() => ({ rule: 'plant', path: p })));
  return [...sites, { rule: 'plant', path: 'lib/out.ts' }];
}
